import pyparsing as pp
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase

R_PAR = pp.Literal(')').suppress()
L_PAR = pp.Literal('(').suppress()
A3_OFFSET = pp.Literal('a3_Offset=').suppress()
REPORT_ON_LEAVE = pp.Literal('reportOnLeave=').suppress()
THRESHOLD = pp.Literal('Threshold:').suppress()
THRESHOLD_ID = pp.Word(pp.nums + ':').suppress() + THRESHOLD
VALUE = pp.Word(pp.nums).setParseAction(lambda toks: int(toks[0]))
BOOL_VALUE = pp.Word(pp.alphas).setParseAction(lambda toks: True if toks[0] == 'true' else False)
RSRP = pp.Literal('RSRP')
RSRQ = pp.Literal('RSRQ')

A124_PARSER = THRESHOLD + (RSRP | RSRQ) + VALUE
A3_PARSER = L_PAR + A3_OFFSET + VALUE + REPORT_ON_LEAVE + BOOL_VALUE + R_PAR
A5_PARSER = THRESHOLD_ID + (RSRP | RSRQ) + VALUE + THRESHOLD_ID + (RSRP | RSRQ) + VALUE


def _parse_a1(event_details):
    details = A124_PARSER.parseString(event_details).asList()
    return {'threshold-{}'.format(details[0]): details[1]}


def _parse_a2(event_details):
    details = A124_PARSER.parseString(event_details).asList()
    return {'threshold-{}'.format(details[0]): details[1]}


def _parse_a3(event_details):
    details = A3_PARSER.parseString(event_details)
    return {'a3-Offset': details[0], 'reportOnLeave': details[1]}


def _parse_a4(event_details):
    details = A124_PARSER.parseString(event_details).asList()
    return {'threshold-{}'.format(details[0]): details[1]}


def _parse_a5(event_details):
    details = A5_PARSER.parseString(event_details)
    return {'threshold1-{}'.format(details[0]): details[1],
            'threshold2-{}'.format(details[2]): details[3]}


eventId_function = {'EventA1': _parse_a1,
                    'EventA2': _parse_a2,
                    'EventA3': _parse_a3,
                    'EventA4': _parse_a4,
                    'EventA5': _parse_a5}


def _parse_specific_event_details(toks):
    eventId, event_details = [tok.strip() for tok in toks[0].split(':', 1)]
    event_details = eventId_function[eventId](event_details)
    return {eventId: event_details}


COMA = pp.Literal(',').suppress()
COLON = pp.Literal(':').suppress()
LINE_END = pp.lineEnd.suppress()
MEASUREMENT_OBJECTS = pp.Literal('MEASUREMENT OBJECTS').suppress()
UE = pp.Regex(r'UE\d+')
TRIGGER_EVENT_STR = UE + pp.Literal('TRIGGER EVENT for report configuration').suppress()
MEAS_OBJECT_ID = pp.Word(pp.nums).setResultsName('measObjectId').setParseAction(lambda toks: int(toks[0]))
REPORT_CONFIG_ID = pp.Word(pp.nums).setResultsName('reportConfigId').setParseAction(lambda toks: int(toks[0]))
MEAS_ID = pp.Word(pp.nums).setResultsName('measId').setParseAction(lambda toks: int(toks[0]))
RAT = pp.Word('EUTRAN').setResultsName('measObject')
CARRIER_FREQ = pp.Word(pp.nums).setResultsName('carrierFreq')
OFFSET_FREQ = pp.Literal('-').setResultsName('offsetFreq')
ALLOWED_BANDWIDTH = (pp.Word(pp.nums) + pp.Literal('rbs')).setParseAction(lambda toks: ' '.join(toks)).setResultsName('allowedMeasBandwidth')
ANTENNA_PORT_1 = pp.Or([pp.Word('on'), pp.Word('off')]).setResultsName('presenceAntennaPort1')
NEIGH_CELL_CONFIG = pp.Word(pp.nums + 'b').setResultsName('neighCellConfig')
CELL_FOR_CGI = pp.Literal('-').setResultsName('cellForWhichToReportCGI')
REDUCED_MEAS_PERFORMANCE = pp.Literal('-').setResultsName('reducedMeasPerformance-r12')
EVENT_TYPE = pp.Word('Event', pp.alphanums + '-').setResultsName('eventId')
TRIGGER_QTY = pp.Or([pp.Word('rsrp'), pp.Word('rsrq')]).setResultsName('triggerQuantity')
REPORT_QTY = pp.Or([pp.Word('both'), pp.Word('same')]).setResultsName('reportQuantity')
MAX_REPORT_CELLS = pp.Word(pp.nums).setResultsName('maxReportCells')
REPORT_INTERVAL = (pp.Word(pp.nums) + (pp.Literal('ms') | pp.Literal('min'))).setParseAction(lambda toks: ' '.join(toks)).setResultsName('reportInterval')
REPORT_AMOUNT = pp.Or([pp.Literal('infinite'), pp.Word(pp.nums)]).setResultsName('reportAmount')
TRIGGER_TYPE = pp.Literal('Type:').suppress() + (pp.Word(pp.alphas)).setResultsName('triggerType')
TRIGGER_HYSTERESIS = pp.Literal('hysteresis:').suppress() + (pp.Word(pp.nums)).setResultsName('hysteresis')
TIME_TO_TRIGGER = pp.Literal('TimeToTrigger:').suppress() + (
    (pp.Word(pp.nums) + (pp.Literal('ms') | pp.Literal('min'))).setParseAction(lambda toks: ' '.join(toks))).setResultsName('timeToTrigger')
TRIGGER_EVENT = pp.restOfLine.setParseAction(_parse_specific_event_details).setResultsName('event')

UE_MEASUREMENT_OBJECTS = pp.Dict(pp.OneOrMore(pp.Group(MEAS_OBJECT_ID + RAT + CARRIER_FREQ + OFFSET_FREQ)))

UE_EUTRA_MEASUREMENT_OBJECTS = pp.Dict(pp.OneOrMore(pp.Group(
    MEAS_OBJECT_ID + RAT + CARRIER_FREQ + ALLOWED_BANDWIDTH + ANTENNA_PORT_1 + NEIGH_CELL_CONFIG + OFFSET_FREQ + CELL_FOR_CGI + REDUCED_MEAS_PERFORMANCE)))

UE_REPORT_CONFIGURATION = pp.Dict(
    pp.OneOrMore(pp.Group(REPORT_CONFIG_ID + RAT + EVENT_TYPE + TRIGGER_QTY + REPORT_QTY + MAX_REPORT_CELLS + REPORT_INTERVAL + REPORT_AMOUNT)))

DETAILED_REPORT_CONFIGURATION = pp.Dict(pp.OneOrMore(
    pp.Group(TRIGGER_EVENT_STR + REPORT_CONFIG_ID + COLON + TRIGGER_TYPE + COMA + TRIGGER_HYSTERESIS + COMA + TIME_TO_TRIGGER + COMA + TRIGGER_EVENT)))

MEASUREMENT_IDENTITIES = pp.Dict(pp.OneOrMore(pp.Group(MEAS_ID + MEAS_OBJECT_ID + REPORT_CONFIG_ID)))


class UeMeasCfgDispFailure(Exception):
    """
    Exception class for ue_meas_cfg_disp
    """
    pass


class UeMeasCfgDisp(EgateCommandBase):
    def __init__(self, **params):
        """

        :param params:
        """
        super(UeMeasCfgDisp, self).__init__()
        self.command = 'ue_meas_cfg_disp'
        self.params = params
        self.to_execute = self.command
        self.executed_phrase = r'.*?UE.*?EGATE>'
        self.fail_regexp = "Error:|ERR|isn't active"
        self._build_command()

    def execute_and_parse(self, egate_id=0):
        """
        Execute ue_meas_cfg_disp command.
        :return: command status and output
        """
        status, output = super(UeMeasCfgDisp, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            parsed_output = self._parse(output)
            return parsed_output
        else:
            raise UeMeasCfgDispFailure(output)

    def _build_command(self):
        """
        Build ue_meas_cfg_disp command.
        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    def _parse(self, raw_output):
        ue_meas_objects = {meas_object.asDict()['measObjectId']: meas_object.asDict()
                           for meas_object in UE_MEASUREMENT_OBJECTS.searchString(raw_output)[0]}
        ue_eutra_meas_objects = {meas_object.asDict()['measObjectId']: meas_object.asDict()
                                 for meas_object in UE_EUTRA_MEASUREMENT_OBJECTS.searchString(raw_output)[0]}
        ue_report_configurations = {report_config.asDict()['reportConfigId']: report_config.asDict()
                                    for report_config in UE_REPORT_CONFIGURATION.searchString(raw_output)[0]}
        detailed_report_configuration = {report_config.asDict()['reportConfigId']: report_config.asDict()
                                         for report_config in DETAILED_REPORT_CONFIGURATION.searchString(raw_output)[0]}
        measurement_identities = {measId.asDict()['measId']: measId.asDict()
                                  for measId in MEASUREMENT_IDENTITIES.searchString(raw_output)[0]}

        all_meas_objects = [ue_eutra_meas_objects]

        for meas_object in all_meas_objects:
            for meas_obj_id, meas_obj in meas_object.items():
                ue_meas_objects[meas_obj_id].update(meas_obj)

        for report_cfg_id, report_cfg in detailed_report_configuration.items():
            ue_report_configurations[report_cfg_id].update(report_cfg)

        return {'measObjects': ue_meas_objects,
                'reportConfigs': ue_report_configurations,
                'measIds': measurement_identities}
